import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const POST_TYPES = ['NOTICE', 'POST'];
const SCOPES = ['ALL', 'DEPARTMENT', 'INDIVIDUAL'];
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function textOf(value: unknown, label: string): string {
  if (typeof value !== 'string' || value.trim() === '') {
    throw invalid(label + '을(를) 입력해 주세요.');
  }
  return value.trim();
}

function idsOf(value: unknown, label: string): number[] {
  if (value === undefined || value === null) {
    return [];
  }
  if (!Array.isArray(value)) {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  const out: number[] = [];
  for (const item of value) {
    const n = Number(item);
    if (!Number.isInteger(n) || n <= 0) {
      throw invalid(label + ' 형식이 올바르지 않습니다.');
    }
    if (!out.includes(n)) {
      out.push(n);
    }
  }
  return out;
}

function dateOf(value: unknown, label: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string' || !DATE_RE.test(value)) {
    throw invalid(label + ' 형식이 올바르지 않습니다. (YYYY-MM-DD)');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr03401Controller {
  @Post('/posts')
  @HttpCode(200)
  async createPost(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);

    const postType = textOf(data['postType'], '구분');
    if (!POST_TYPES.includes(postType)) {
      throw invalid('구분 값이 올바르지 않습니다.');
    }
    const category = textOf(data['category'], '분류');
    const title = textOf(data['title'], '제목');
    const content = textOf(data['content'], '내용');
    const scope = textOf(data['visibilityScope'], '공개범위');
    if (!SCOPES.includes(scope)) {
      throw invalid('공개범위 값이 올바르지 않습니다.');
    }
    const departmentIds = idsOf(data['targetDepartmentIds'], '대상 부서');
    const employeeIds = idsOf(data['targetEmployeeIds'], '대상 임직원');
    const popupStart = dateOf(data['popupStartDate'], '팝업공지 시작일');
    const popupEnd = dateOf(data['popupEndDate'], '팝업공지 종료일');
    const pinStart = dateOf(data['pinStartDate'], '상단 고정 시작일');
    const pinEnd = dateOf(data['pinEndDate'], '상단 고정 종료일');
    if ((popupStart === null) !== (popupEnd === null)) {
      throw invalid('팝업공지 시작일과 종료일을 함께 입력해 주세요.');
    }
    if ((pinStart === null) !== (pinEnd === null)) {
      throw invalid('상단 고정 시작일과 종료일을 함께 입력해 주세요.');
    }

    if (scope === 'DEPARTMENT' && departmentIds.length === 0) {
      throw new ApiError(422, 'POST_TARGET_REQUIRED', '공개 대상 부서를 지정해 주세요.');
    }
    if (scope === 'INDIVIDUAL' && employeeIds.length === 0) {
      throw new ApiError(422, 'POST_TARGET_REQUIRED', '공개 대상 임직원을 지정해 주세요.');
    }
    const targetDepartments = scope === 'DEPARTMENT' ? departmentIds : [];
    const targetEmployees = scope === 'INDIVIDUAL' ? employeeIds : [];

    return transaction(async (db) => {
      const period = await db.query(
        'SELECT (CAST(:popupStart AS date) > CAST(:popupEnd AS date)) AS "popupBad", (CAST(:pinStart AS date) > CAST(:pinEnd AS date)) AS "pinBad"',
        { popupStart, popupEnd, pinStart, pinEnd },
      );
      if (period[0] && (period[0]['popupBad'] === true || period[0]['pinBad'] === true)) {
        throw new ApiError(422, 'INVALID_PERIOD', '종료일은 시작일보다 빠를 수 없습니다.');
      }

      for (const id of targetDepartments) {
        const found = await db.query(
          'SELECT department_id FROM department WHERE department_id = CAST(:id AS bigint)',
          { id },
        );
        if (found.length === 0) {
          throw invalid('존재하지 않는 부서가 포함되어 있습니다.');
        }
      }
      for (const id of targetEmployees) {
        const found = await db.query(
          'SELECT employee_id FROM employee WHERE employee_id = CAST(:id AS bigint)',
          { id },
        );
        if (found.length === 0) {
          throw invalid('존재하지 않는 임직원이 포함되어 있습니다.');
        }
      }

      const rows = await db.query(
        'INSERT INTO post (author_id, post_type, category, title, content, visibility_scope, popup_start_date, popup_end_date, pin_start_date, pin_end_date, created_at, updated_at) ' +
          'VALUES (CAST(:userId AS bigint), :postType, :category, :title, :content, :scope, CAST(:popupStart AS date), CAST(:popupEnd AS date), CAST(:pinStart AS date), CAST(:pinEnd AS date), now(), now()) ' +
          'RETURNING post_id AS "postId", post_type AS "postType", category AS "category", title AS "title", visibility_scope AS "visibilityScope", ' +
          'to_char(popup_start_date, \'YYYY-MM-DD\') AS "popupStartDate", to_char(popup_end_date, \'YYYY-MM-DD\') AS "popupEndDate", ' +
          'to_char(pin_start_date, \'YYYY-MM-DD\') AS "pinStartDate", to_char(pin_end_date, \'YYYY-MM-DD\') AS "pinEndDate"',
        { userId: user.id, postType, category, title, content, scope, popupStart, popupEnd, pinStart, pinEnd },
      );
      const created = rows[0];

      for (const id of targetDepartments) {
        await db.execute(
          'INSERT INTO post_target (post_id, department_id, created_at, updated_at) VALUES (CAST(:postId AS bigint), CAST(:id AS bigint), now(), now())',
          { postId: created['postId'], id },
        );
      }
      for (const id of targetEmployees) {
        await db.execute(
          'INSERT INTO post_target (post_id, target_employee_id, created_at, updated_at) VALUES (CAST(:postId AS bigint), CAST(:id AS bigint), now(), now())',
          { postId: created['postId'], id },
        );
      }

      return created;
    });
  }
}

