import { useState } from 'react';
import {
  Band,
  Badge,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Form,
  LookupSelect,
  RefName,
  Select,
  TextInput,
  Tiles,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

const POST_TYPE_OPTIONS: [string, string][] = [
  ['NOTICE', '공지사항'],
  ['POST', '게시물'],
];

const SCOPE_OPTIONS: [string, string][] = [
  ['ALL', '전체'],
  ['DEPARTMENT', '부서'],
  ['INDIVIDUAL', '개인'],
];

function labelOf(options: [string, string][], value: unknown): string {
  const found = options.find((o) => o[0] === value);
  return found ? found[1] : String(value ?? '');
}

function periodText(start: unknown, end: unknown) {
  if (!start || !end) {
    return <span>미설정</span>;
  }
  return (
    <span>
      <DateText value={start} /> ~ <DateText value={end} />
    </span>
  );
}

export default function FnSfr03401Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [detail, setDetail] = useState<Row | null>(null);
  const [postType, setPostType] = useState('');
  const [category, setCategory] = useState('');
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [scope, setScope] = useState('');
  const [departmentIds, setDepartmentIds] = useState<number[]>([]);
  const [employeeIds, setEmployeeIds] = useState<number[]>([]);
  const [pickDepartment, setPickDepartment] = useState<number | string>('');
  const [pickEmployee, setPickEmployee] = useState<number | string>('');
  const [popupStart, setPopupStart] = useState('');
  const [popupEnd, setPopupEnd] = useState('');
  const [pinStart, setPinStart] = useState('');
  const [pinEnd, setPinEnd] = useState('');

  function resetForm() {
    setPostType('');
    setCategory('');
    setTitle('');
    setContent('');
    setScope('');
    setDepartmentIds([]);
    setEmployeeIds([]);
    setPickDepartment('');
    setPickEmployee('');
    setPopupStart('');
    setPopupEnd('');
    setPinStart('');
    setPinEnd('');
  }

  function openForm() {
    resetForm();
    setOpen(true);
  }

  function addDepartment() {
    const id = Number(pickDepartment);
    if (id && !departmentIds.includes(id)) {
      setDepartmentIds([...departmentIds, id]);
    }
    setPickDepartment('');
  }

  function addEmployee() {
    const id = Number(pickEmployee);
    if (id && !employeeIds.includes(id)) {
      setEmployeeIds([...employeeIds, id]);
    }
    setPickEmployee('');
  }

  async function submit() {
    if (!postType) {
      throw new Error('구분을 선택해 주세요.');
    }
    if (!category.trim()) {
      throw new Error('분류를 입력해 주세요.');
    }
    if (!title.trim()) {
      throw new Error('제목을 입력해 주세요.');
    }
    if (!content.trim()) {
      throw new Error('내용을 입력해 주세요.');
    }
    if (!scope) {
      throw new Error('공개범위를 선택해 주세요.');
    }
    if (scope === 'DEPARTMENT' && departmentIds.length === 0) {
      throw new Error('공개 대상 부서를 지정해 주세요.');
    }
    if (scope === 'INDIVIDUAL' && employeeIds.length === 0) {
      throw new Error('공개 대상 임직원을 지정해 주세요.');
    }
    if ((popupStart && !popupEnd) || (!popupStart && popupEnd)) {
      throw new Error('팝업공지 시작일과 종료일을 함께 입력해 주세요.');
    }
    if ((pinStart && !pinEnd) || (!pinStart && pinEnd)) {
      throw new Error('상단 고정 시작일과 종료일을 함께 입력해 주세요.');
    }
    if (popupStart && popupEnd && popupEnd < popupStart) {
      throw new Error('팝업공지 종료일은 시작일보다 빠를 수 없습니다.');
    }
    if (pinStart && pinEnd && pinEnd < pinStart) {
      throw new Error('상단 고정 종료일은 시작일보다 빠를 수 없습니다.');
    }
    const body: Row = {
      postType,
      category: category.trim(),
      title: title.trim(),
      content: content.trim(),
      visibilityScope: scope,
    };
    if (scope === 'DEPARTMENT') {
      body.targetDepartmentIds = departmentIds;
    }
    if (scope === 'INDIVIDUAL') {
      body.targetEmployeeIds = employeeIds;
    }
    if (popupStart && popupEnd) {
      body.popupStartDate = popupStart;
      body.popupEndDate = popupEnd;
    }
    if (pinStart && pinEnd) {
      body.pinStartDate = pinStart;
      body.pinEndDate = pinEnd;
    }
    const created = await call<Row>('POST', '/posts', role, body);
    setResults([created, ...results]);
    notify('공지·게시물을 등록했습니다.');
    setOpen(false);
  }

  const popupCount = results.filter((r) => r.popupStartDate).length;
  const pinCount = results.filter((r) => r.pinStartDate).length;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>등록 현황</h2>
        <Tiles
          items={[
            ['이번 접속 등록', results.length],
            ['팝업공지 설정', popupCount],
            ['상단 고정 설정', pinCount],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>등록 결과</h2>
        <Band total={results.length}>
          <button type="button" onClick={openForm}>
            공지·게시물 등록
          </button>
        </Band>
        <DataTable
          rows={results}
          empty="이 화면에서 등록한 공지·게시물이 없습니다."
          onRowClick={(row) => setDetail(row)}
          columns={[
            { key: 'postId', label: '공지·게시물 ID' },
            { key: 'postType', label: '구분', render: (r) => <Badge value={labelOf(POST_TYPE_OPTIONS, r.postType)} /> },
            { key: 'category', label: '분류' },
            { key: 'title', label: '제목' },
            { key: 'visibilityScope', label: '공개범위', render: (r) => <span>{labelOf(SCOPE_OPTIONS, r.visibilityScope)}</span> },
            { key: 'popup', label: '팝업공지 기간', render: (r) => periodText(r.popupStartDate, r.popupEndDate) },
            { key: 'pin', label: '상단 고정 기간', render: (r) => periodText(r.pinStartDate, r.pinEndDate) },
          ]}
        />
      </section>

      {open && (
        <Drawer title="공지·게시물 등록" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="등록">
            <Field label="구분" required>
              <Select value={postType} onChange={setPostType} options={POST_TYPE_OPTIONS} />
            </Field>
            <Field label="분류" required>
              <TextInput value={category} onChange={setCategory} />
            </Field>
            <Field label="제목" required wide>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label="내용" required wide>
              <TextInput value={content} onChange={setContent} multiline />
            </Field>
            <Field label="공개범위" required>
              <Select value={scope} onChange={setScope} options={SCOPE_OPTIONS} />
            </Field>
            {scope === 'DEPARTMENT' && (
              <Field label="대상 부서" required wide hint="부서를 고른 뒤 추가를 누르세요.">
                <LookupSelect table="department" role={role} value={pickDepartment} onChange={setPickDepartment} />
                <button type="button" onClick={addDepartment}>
                  추가
                </button>
                <ul>
                  {departmentIds.map((id) => (
                    <li key={id}>
                      <RefName table="department" role={role} value={id} />{' '}
                      <button type="button" onClick={() => setDepartmentIds(departmentIds.filter((x) => x !== id))}>
                        삭제
                      </button>
                    </li>
                  ))}
                </ul>
              </Field>
            )}
            {scope === 'INDIVIDUAL' && (
              <Field label="대상 임직원" required wide hint="임직원을 고른 뒤 추가를 누르세요.">
                <LookupSelect table="employee" role={role} value={pickEmployee} onChange={setPickEmployee} />
                <button type="button" onClick={addEmployee}>
                  추가
                </button>
                <ul>
                  {employeeIds.map((id) => (
                    <li key={id}>
                      <RefName table="employee" role={role} value={id} />{' '}
                      <button type="button" onClick={() => setEmployeeIds(employeeIds.filter((x) => x !== id))}>
                        삭제
                      </button>
                    </li>
                  ))}
                </ul>
              </Field>
            )}
            <Field label="팝업공지 시작일">
              <DateInput value={popupStart} onChange={setPopupStart} />
            </Field>
            <Field label="팝업공지 종료일">
              <DateInput value={popupEnd} onChange={setPopupEnd} />
            </Field>
            <Field label="상단 고정 시작일">
              <DateInput value={pinStart} onChange={setPinStart} />
            </Field>
            <Field label="상단 고정 종료일">
              <DateInput value={pinEnd} onChange={setPinEnd} />
            </Field>
          </Form>
        </Drawer>
      )}

      {detail && (
        <Drawer title="등록 결과" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['공지·게시물 ID', String(detail.postId ?? '')],
              ['구분', labelOf(POST_TYPE_OPTIONS, detail.postType)],
              ['분류', String(detail.category ?? '')],
              ['제목', String(detail.title ?? '')],
              ['공개범위', labelOf(SCOPE_OPTIONS, detail.visibilityScope)],
              ['팝업공지 기간', periodText(detail.popupStartDate, detail.popupEndDate)],
              ['상단 고정 기간', periodText(detail.pinStartDate, detail.pinEndDate)],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
